      "BaseObjectType": 17,
      "OrderEntry": "{v.DocEntry}",
      "OrderRowID": "{i}",
      "ReleasedQuantity": {v.Quantity}
    }}
    """
    qs_arr.append(qs_i)
  item.json.qs = ','.join(qs_arr)
return _input.all()

for item in _input.all():
  reasons = set()
  if item.json.order_value_check == "Failed":
    reasons.add("Total Order Value")
  reasons = sorted(list(reasons))
  item.json.failed_reason = " and ".join(reasons)
  item.json.comments = "On Hold Reason: " + item.json.failed_reason + "; " + item.json.comments

return _input.all()

import json

def extract_failed_reason(message):
  json_str = message.split("400 - ", 1)[1]
  clean = json_str.strip('"').encode("utf-8").decode("unicode_escape")
  parsed = json.loads(clean)
  return parsed["error"]["message"]["value"]

for item in _input.all():
  if item.json.error.message.startswith('400 - '):
    item.json.failed_reason = extract_failed_reason(item.json.error.message)
  else:
    item.json.failed_reason = item.json.error.message

return _input.all()

import re

def fn_order_value_check(order_value):
  order_value = float(order_value)
  if order_value is None or order_value == "":
    return "Failed"

  if order_value > 0 and order_value < 1200:
    return "Passed"
  else: return "Failed"

# Loop over input items and add a new field called 'myNewField' to the JSON of each one
for item in _input.all():
  if item.json.risk_level == "MEDIUM" or item.json.risk_level == "HIGH":
    continue

  item.json.order_value_check = fn_order_value_check(item.json.current_subtotal_price)

  if item.json.order_value_check == "Passed":
    item.json.all_check = "Passed"
  else:
    item.json.all_check = "Failed"

return _input.all()

